mapper.select:
SELECT 
  FROM USER_CONSENT
 WHERE USER_ID = #{userId}
   AND CONSENT_ID = #{consentId}
   AND CONSENT_TYPE_CODE = 'ALT_DATA_PROVISION'

mapper.update:
UPDATE USER_CONSENT
   SET WITHDRAWN_AT = #{now}
 WHERE CONSENT_ID = #{consentId}
   AND WITHDRAWN_AT IS NULL

UPDATE USER_CONSENT
   SET EXTERNAL_CONSENT_ID = #{externalConsentId}
 WHERE CONSENT_ID = #{consentId}
